command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: KALTE WUT (Rondra)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (!globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }
    if (!globalThis.DSK) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework fehlt!");
    const DSK_FW = globalThis.DSK; 

    // --- 2. WIRKENDEN PRÜFEN & QS HOLEN (Panzerglas-Schutz!) ---
    let casterToken = canvas.tokens.controlled[0];
    const casterActor = casterToken?.actor || game.user.character;
    if (!casterActor) return ui.notifications.warn("Bitte wähle zuerst deinen Token aus!");

    if (!casterToken) casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor.id);

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) await casterActor.unsetFlag("world", "letzteGabenQS"); 

    let rollData = (typeof testData !== "undefined" && testData) ? testData : ((typeof args !== "undefined" && args[0]) ? args[0] : null);
    if (rollData && (rollData.qualityStep !== undefined || rollData.result?.QL !== undefined)) {
        qsWert = Number(rollData.qualityStep || rollData.result?.QL || 1);
    } else {
        const lastRollMsg = game.messages.contents.slice().reverse().find(m => 
            m.speaker?.actor === casterActor.id && m.content && m.content.includes("Qualitätsstufe")
        );
        if (lastRollMsg) {
            const qsMatch = lastRollMsg.content.match(/Qualitätsstufe(?:[^0-9]+)(\d+)/i);
            if (qsMatch && qsMatch[1]) qsWert = Number(qsMatch[1]);
        }
    }

    const gabenName = "Kalte Wut";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const dauerKR = qsWert * 5;
    const iconBild = DSK_FW.Symbol(ahne);

    // --- 3. ALTE EFFEKTE LÖSCHEN ---
    for (let ef of casterActor.effects) { 
        if ((ef.name || ef.label) === finalEffektName) await ef.delete(); 
    }

    // --- 4. ENDEKARTE REGISTRIEREN ---
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("kalteWut", finalEffektName, "Die Kalte Wut verraucht. Das Rondrakind beruhigt sich und der Rausch endet.");
    }

    // --- 5. EFFEKT (MIT EXAKTEN RASEREI-WERTEN) ANWENDEN ---
    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        description: `Das Rondrakind befindet sich in einem Kampfrausch und profitiert vom Status <b>Raserei</b>.`,
        duration: { 
            rounds: dauerKR,           // Zählt im Kampf-Tracker automatisch runter!
            seconds: dauerKR * 5       // Fallback für außerhalb des Kampfes
        },
        // HIER SIND DIE EXAKTEN WERTE AUS DEINEM SYSTEM-CODE:
        changes: [
            { key: "system.meleeStats.attack", mode: 2, value: "4" },
            { key: "system.meleeStats.parry", mode: 2, value: "-100" },
            { key: "system.rangeStats.attack", mode: 2, value: "-100" }
        ],
        // Dieser Status-Tag verknüpft den Effekt direkt mit der System-Logik für "Raserei"
        statuses: ["bloodrush"],
        flags: { dsk: { qs: qsWert } }
    }]);

    // --- 6. CHAT-KARTE FÜR WIRKUNGSBEGINN ---
    await ChatMessage.create({
        speaker: { alias: "System" },
        content: `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px; text-align:center;">
                    <p style="margin-bottom: 8px; font-size:1.05em;"><b>${casterName}</b> verfällt in einen unaufhaltsamen Zorn!</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">
                        Das Rondrakind wird von der Kalten Wut gepackt und ist nun in Raserei!<br><br>
                        <span style="font-size:0.9em; color:#8b0000;">
                            <b>Nahkampf:</b> Attacke +4, Parade nicht mehr möglich<br>
                            <b>Fernkampf:</b> Nicht mehr möglich
                        </span>
                    </p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px; font-weight:bold;">Wirkungsdauer:<br>${dauerKR} Kampfrunden</p>
                </div>
            </div>
        `
    });
})();
